def parse_payouts(rows):
    total = 0.0
    parsed = 0
    errors = []
    for i, row in enumerate(rows):
        if not isinstance(row, dict):
            raise TypeError(f'row {i} must be a dict, got {type(row).__name__}')
        order_id = row.get('order_id')
        if 'amount' not in row:
            errors.append({'row': i, 'order_id': order_id, 'error': 'missing amount'})
            continue
        raw = row['amount']
        try:
            amount = float(str(raw).replace(',', ''))
        except ValueError:
            errors.append({'row': i, 'order_id': order_id, 'error': f'invalid amount: {raw!r}'})
            continue
        total += amount
        parsed += 1
    return {'total': round(total, 2), 'parsed': parsed, 'errors': errors}
